import {aggregateScores, pickMission, csvForNotes} from './logic.js';
const $=id=>document.getElementById(id);
let current=null,busy=false,recorder=null,stream=null,recordTimer=null,recordTick=null,cancelled=false,worker=null;
let serial=0;
const pending=new Map();
let notes=[];
try{const saved=JSON.parse(localStorage.getItem('soundwalk-notes')||'[]');if(Array.isArray(saved)) notes=saved.filter(n=>typeof n.note==='string'&&typeof n.title==='string'&&typeof n.date==='string'&&Array.isArray(n.scores)).slice(-100);}catch{}
function status(message,error=false){$('status').textContent=message;$('status').classList.toggle('error',error);}
function setBusy(value){busy=value;for(const id of ['record','audio-file','demo']) $(id).disabled=value;}
function getWorker(){if(!worker){worker=new Worker(new URL('./model-worker.js',import.meta.url),{type:'module'});worker.onmessage=({data})=>{const item=pending.get(data.id);if(!item)return;clearTimeout(item.timer);pending.delete(data.id);data.error?item.reject(new Error(data.error)):item.resolve(data);};worker.onerror=()=>{for(const item of pending.values()){clearTimeout(item.timer);item.reject(new Error('The local model could not start. Please reload and try again.'));}pending.clear();worker?.terminate();worker=null;};}return worker;}
function infer(samples,rate){return new Promise((resolve,reject)=>{const id=++serial;const timer=setTimeout(()=>{pending.delete(id);worker?.terminate();worker=null;for(const item of pending.values()){clearTimeout(item.timer);item.reject(new Error('The local model took too long to respond.'));}pending.clear();reject(new Error('The local model took too long to load. Check your connection and try again.'));},60000);pending.set(id,{resolve,reject,timer});getWorker().postMessage({id,samples,rate},[samples.buffer]);});}
async function classifyBlob(blob,source){if(blob.size>10*1024*1024)throw new Error('Choose a file smaller than 10 MB.');const Context=window.AudioContext||window.webkitAudioContext;const ctx=new Context();try{const audio=await ctx.decodeAudioData(await blob.arrayBuffer());if(!audio.length||audio.duration<1||audio.duration>30)throw new Error('Choose a recording between 1 and 30 seconds.');const mono=new Float32Array(audio.length);for(let c=0;c<audio.numberOfChannels;c++){const channel=audio.getChannelData(c);for(let i=0;i<mono.length;i++)mono[i]+=channel[i]/audio.numberOfChannels;}status('Listening with the local model… First use downloads the model.');const output=await infer(mono,audio.sampleRate);const scores=aggregateScores(output.results);if(!scores.length)throw new Error('No sound suggestions were returned. Try a different recording.');current={scores,source,duration:audio.duration,inferenceMs:output.inferenceMs};renderResult();status(`Suggestions ready · ${(output.inferenceMs/1000).toFixed(1)}s model time.`);}finally{await ctx.close();}}
function renderResult(){const top=current.scores[0];$('empty-result').hidden=true;$('sound-result').hidden=false;$('sound-title').textContent=top.score<.2?'A sound worth listening to':top.label;$('source-note').textContent=`${current.source} · ${current.duration.toFixed(1)} seconds · model suggestions`;$('scores').replaceChildren();for(const item of current.scores.slice(0,3)){const row=document.createElement('div');row.className='score-row';const label=document.createElement('span');label.textContent=item.label;const score=document.createElement('span');score.textContent=item.score.toFixed(3);row.append(label,score);const bar=document.createElement('div');bar.className='score-bar';const fill=document.createElement('span');fill.style.width=`${Math.max(0,Math.min(1,item.score))*100}%`;bar.append(fill);$('scores').append(row,bar);}$('note').value='';$('save').disabled=false;const mission=pickMission(current.scores);$('mission-title').textContent=mission.title;$('mission-text').textContent=mission.text;}
async function withAudio(blob,source){setBusy(true);current=null;$('sound-result').hidden=true;$('empty-result').hidden=false;try{await classifyBlob(blob,source);}catch(e){status(e.message||'Could not read this audio. Try a short WAV recording.',true);}finally{setBusy(false);}}
$('audio-file').addEventListener('change',async event=>{const file=event.target.files?.[0];if(!file||busy)return;await withAudio(file,'Your audio file');event.target.value='';});
$('demo').addEventListener('click',async()=>{if(busy)return;setBusy(true);const sample=$('demo-choice').value;const files={birds:['birds.wav','Birdsong reference · jmiddlesworth · CC0'],rain:['rain.wav','Rain reference · InspectorJ · CC BY 4.0'],synthetic:['synthetic-rain.wav','Synthetic rain-like test audio']};const [file,source]=files[sample]||files.synthetic;try{const r=await fetch('./samples/'+file);if(!r.ok)throw new Error('The reference audio could not be loaded.');await withAudio(await r.blob(),source);}catch(e){status(e.message,true);setBusy(false);}});
function stopTracks(){stream?.getTracks().forEach(t=>t.stop());stream=null;clearTimeout(recordTimer);clearInterval(recordTick);$('cancel').hidden=true;document.body.classList.remove('recording');}
$('record').addEventListener('click',async()=>{if(busy)return;if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){status('Recording is unavailable here. Choose a short audio file instead.',true);return;}setBusy(true);cancelled=false;try{stream=await navigator.mediaDevices.getUserMedia({audio:true});const parts=[];recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>{if(e.data.size)parts.push(e.data);};recorder.onerror=()=>{cancelled=true;stopTracks();setBusy(false);status('Recording stopped unexpectedly. Try choosing an audio file.',true);};recorder.onstop=async()=>{const mime=recorder.mimeType;recorder=null;stopTracks();if(cancelled){setBusy(false);status('Recording discarded.');return;}await withAudio(new Blob(parts,{type:mime}),'Your 8-second recording');};recorder.start();$('cancel').hidden=false;document.body.classList.add('recording');let remaining=8;status(`Recording · ${remaining}s remaining. Listen, then put your phone away.`);recordTick=setInterval(()=>status(`Recording · ${Math.max(0,--remaining)}s remaining.`),1000);recordTimer=setTimeout(()=>recorder?.state==='recording'&&recorder.stop(),8000);}catch(e){stopTracks();setBusy(false);status(e.name==='NotAllowedError'?'Microphone permission was not granted. You can choose a file instead.':'Could not start recording. Choose a file instead.',true);}});
$('cancel').addEventListener('click',()=>{cancelled=true;if(recorder?.state==='recording')recorder.stop();else{stopTracks();setBusy(false);}});
$('save').addEventListener('click',()=>{if(!current)return;const note=$('note').value.trim();const observation={title:current.scores[0].score<.2?'Uncertain sound':current.scores[0].label,note,date:new Date().toISOString(),source:current.source,scores:current.scores.slice(0,3)};const next=[...notes,observation].slice(-100);try{localStorage.setItem('soundwalk-notes',JSON.stringify(next));notes=next;renderJournal();$('save').disabled=true;status('Observation kept on this device. Time to go listen again.');}catch{status('This browser could not save the note. Local storage may be full or disabled.',true);}});
function renderJournal(){$('count').textContent=notes.length;$('export').disabled=!notes.length;$('empty-journal').hidden=!!notes.length;$('notes').replaceChildren();for(const note of [...notes].reverse()){const entry=document.createElement('article');entry.className='entry';const title=document.createElement('strong');title.textContent=note.title;const date=document.createElement('time');date.dateTime=note.date;date.textContent=new Date(note.date).toLocaleDateString();const body=document.createElement('p');body.textContent=note.note||'A pause to listen.';const source=document.createElement('p');source.className='small';source.textContent=note.source||'Saved observation';entry.append(title,date,body,source);$('notes').append(entry);}}
$('export').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([csvForNotes(notes)],{type:'text/csv;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='soundwalk-field-notes.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
renderJournal();
if('serviceWorker' in navigator){navigator.serviceWorker.addEventListener('message',e=>{if(e.data==='OFFLINE_READY')$('offline').textContent='Offline copy ready';if(e.data==='OFFLINE_FAILED')$('offline').textContent='Offline copy unavailable; internet needed';});navigator.serviceWorker.register('./sw.js').then(async registration=>{const active=registration.active;if(active)active.postMessage('CHECK_READY');}).catch(()=>$('offline').textContent='Offline copy unavailable; internet needed');}else $('offline').textContent='This browser needs internet to reopen';
window.addEventListener('pagehide',()=>{cancelled=true;if(recorder?.state==='recording')recorder.stop();stopTracks();});
